#    define CAN_DBC_PACKED
#    define CAN_DBC_ALIGN4    __declspec(align(4))
#    define CAN_DBC_PACK_PUSH __pragma(pack(push, 1))
#    define CAN_DBC_PACK_POP  __pragma(pack(pop))
